package fr.dossierfacile.api.pdfgenerator.service.templates;

/**
 * Content of a sworn statement ("Attestation sur l'honneur") generated by DossierFacile.
 *
 * @param personName  name of the person who makes the statement
 * @param statement   fixed sentence in the first person, printed between quotes
 * @param explanation optional text typed by the tenant, printed below the statement as "Précisions : ..."
 */
public record AttestationContent(String personName, String statement, String explanation) {

    public AttestationContent {
        if (statement == null || statement.isBlank()) {
            throw new IllegalArgumentException("An attestation needs a statement");
        }
    }

}
